def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    me = observation['self_position']
    opponents = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(tuple(pos) for pos in observation['obstacles'])
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    target = None
    min_d = float('inf')
    for res in resources:
        d = dist(me, res)
        if d < min_d:
            min_d = d
            target = res

    def move_towards(target):
        dx = target[0] - me[0]
        dy = target[1] - me[1]
        dx = (dx > 0) - (dx < 0)
        dy = (dy > 0) - (dy < 0)
        # Check for obstacles
        next_pos = (me[0] + dx, me[1] + dy)
        if 0 <= next_pos[0] < width and 0 <= next_pos[1] < height and next_pos not in obstacles:
            return [dx, dy]
        # Try alternative moves
        for delta in [[1,0],[-1,0],[0,1],[0,-1]]:
            new_pos = (me[0]+delta[0], me[1]+delta[1])
            if 0 <= new_pos[0] < width and 0 <= new_pos[1] < height and new_pos not in obstacles:
                return [delta[0], delta[1]]
        return [0,0]

    if target:
        return move_towards(target)
    else:
        # No resources, chase opponent
        return move_towards(opponents)
